-- Fictional starter inventory. Replace with verified Merino VFD apparatus and equipment before operational use.
insert into public.stations(name,address) values ('Merino Volunteer Fire Department','Merino, Colorado') on conflict(name) do nothing;
insert into public.apparatus_types(name) values ('Engine'),('Tender'),('Brush'),('Rescue') on conflict(name) do nothing;
insert into public.equipment_categories(name) values ('SCBA'),('Medical'),('Hose'),('Hand Tools') on conflict(name) do nothing;
with e as (select id from apparatus_types where name='Engine') insert into public.inspection_templates(name,frequency,apparatus_type_id) select 'Engine Daily Readiness','daily',id from e where not exists(select 1 from inspection_templates where name='Engine Daily Readiness');
with t as (select id from inspection_templates where name='Engine Daily Readiness') insert into public.inspection_questions(template_id,question,section,display_order) select t.id,x.question,x.section,x.ord from t cross join (values (1,'Cab, warning lights, and audible warning devices','Cab'),(2,'Pump panel, gauges, and controls','Pump'),(3,'SCBA inventory and cylinder pressure','Safety'),(4,'Tires, fluids, leaks, and exterior condition','Walk-around'),(5,'Fuel level and DEF','Walk-around')) as x(ord,question,section) where not exists(select 1 from inspection_questions q where q.template_id=t.id and q.display_order=x.ord);
with s as(select id from stations where name='Merino Volunteer Fire Department'), t as(select id from apparatus_types where name='Engine'), c as(select id from inspection_templates where name='Engine Daily Readiness') insert into public.apparatus(unit_number,name,station_id,type_id,vin,mileage,fuel_level,status,in_service,checklist_id) select 'E-101','Training Engine 101',s.id,t.id,'DEMO-REPLACE-BEFORE-USE',0,100,'available',true,c.id from s,t,c where not exists(select 1 from apparatus where unit_number='E-101');
